INSERT INTO `news` (`id`, `title`, `text`, `picture`, `category_id`, `user_id`) VALUES
(1, 'Autonomous AI Agents Transforming Global Software Engineering', 'Autonomous artificial intelligence agents are reshaping modern software development workflows worldwide. Industry reports indicate that AI-assisted pair programming and self-healing deployment pipelines have increased developer velocity by over 40% this quarter. Engineering teams are leveraging deep code intelligence to automate verification, optimize database queries, and accelerate feature shipping safely.', , 1, 1),
(2, 'Clean Energy Breakthrough: Fusion Reactor Sustains Net Power Output', 'Physicists and energy researchers have announced a milestone in magnetic confinement fusion. The experimental reactor sustained continuous net positive power output across multiple cycles, marking a transformative leap towards limitless, carbon-free energy for industrial power grids. Global investments in clean fusion tech continue to soar.', , 3, 1),
(3, 'Next-Generation Space Telescope Reveals Exoplanet Atmospheric Spectra', 'Astronomers utilizing newly deployed deep space orbital observatories have captured detailed atmospheric composition signatures of habitable-zone exoplanets. The discovery offers unprecedented insights into terrestrial planet formation and potential biosignature detection beyond our solar system.', , 3, 1),
(4, 'Global Financial Markets Embrace Decentralized Settlement Protocols', 'Major international banking consortiums and financial authorities have begun deploying next-generation settlement protocols. The transition significantly minimizes cross-border transaction delays while enhancing cryptographic security and auditability across liquidity networks.', , 4, 1),
(5, 'World Athletics Championship Concludes with Historic Record Times', 'The 2026 World Athletics Championship concluded this weekend with athletes setting historic records across track and field events. Spectacular performances drew global audiences, setting new benchmarks in athletic endurance and modern sports science preparation.', , 5, 1);

